// UVM 1.2 Inherited Doc Topics for uvm_object
if(window.__registerUvmDocTopics){window.__registerUvmDocTopics("uvm_object",[{"n":"new","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-1","s":"src_view/base/uvm_object.svh.html#L54","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.new\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L54\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"54\">new</a></h3><div class=\"method-meta-bar\"><span class=\"badge-subclass\" title=\"Overridden in 38 derived class(es)\">Overridden in 38 subclasses</span></div>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-keyword-decl\">function</span> <span class=\"sv-proto-name\">new</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">name</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\">&quot;&quot;</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Creates a new uvm_object with the given instance <i>name</i>.&nbsp; If <i>name</i> is not supplied, the object is unnamed.</p></div></div></div>"},{"n":"use_uvm_seeding","k":"variable","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-3","s":"src_view/base/uvm_object.svh.html#L70","h":"<div class=\"CVariable\" data-anchor=\"uvm_object.use_uvm_seeding\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L70\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"70\">use_uvm_seeding</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype><tr><td><span class=\"sv-qualifier\">static</span> <span class=\"sv-type\">bit</span> <span class=\"sv-ident\">use_uvm_seeding</span> <span class=\"sv-op\">=</span><span class=\"sv-ident\"> 1\n  </span></td></tr></table></blockquote><div class=CBody><p>This bit enables or disables the UVM seeding mechanism.&nbsp; It globally affects the operation of the <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-4\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-4\" data-target-id=\"doc-nav-item-4\" class=LMethod  >reseed</a> method.</p><p>When enabled, UVM-based objects are seeded based on their type and full hierarchical name rather than allocation order.&nbsp; This improves random stability for objects whose instance names are unique across each type.&nbsp; The <a href=\"__ROOT_REL__docs_view/base/uvm_component-svh.html#doc-nav-main\" data-doc-href=\"docs_view/base/uvm_component-svh.html#doc-nav-main\" data-target-id=\"doc-nav-main\" class=LClass  >uvm_component</a> class is an example of a type that has a unique instance name.</p></div></div></div>"},{"n":"reseed","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-4","s":"src_view/base/uvm_object.svh.html#L82","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.reseed\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L82\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"82\">reseed</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype><tr><td><span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-proto-name\">reseed</span> <span class=\"sv-op\">(</span><span class=\"sv-op\">)</span>\n  </td></tr></table></blockquote><div class=CBody><p>Calls <i>srandom</i> on the object to reseed the object using the UVM seeding mechanism, which sets the seed based on type name and instance name instead of based on instance position in a thread.</p><p>If the <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-3\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-3\" data-target-id=\"doc-nav-item-3\" class=LVariable  >use_uvm_seeding</a> static variable is set to 0, then reseed() does not perform any function.</p></div></div></div>"},{"n":"set_name","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-6","s":"src_view/base/uvm_object.svh.html#L92","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.set_name\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L92\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"92\">set_name</a></h3><div class=\"method-meta-bar\"><span class=\"badge-subclass\" title=\"Overridden in 1 derived class(es)\">Overridden in 1 subclasses</span></div>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=3><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-proto-name\">set_name</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">name</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=3><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Sets the instance name of this object, overwriting any previously given name.</p></div></div></div>"},{"n":"get_name","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-7","s":"src_view/base/uvm_object.svh.html#L100","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.get_name\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L100\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"100\">get_name</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype><tr><td><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">string</span> <span class=\"sv-proto-name\">get_name</span> <span class=\"sv-op\">(</span><span class=\"sv-op\">)</span>\n  </td></tr></table></blockquote><div class=CBody><p>Returns the name of the object, as provided by the <i>name</i> argument in the <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-1\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-1\" data-target-id=\"doc-nav-item-1\" class=LMethod  >new</a> constructor or <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-6\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-6\" data-target-id=\"doc-nav-item-6\" class=LMethod  >set_name</a> method.</p></div></div></div>"},{"n":"get_full_name","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-8","s":"src_view/base/uvm_object.svh.html#L117","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.get_full_name\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L117\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"117\">get_full_name</a></h3><div class=\"method-meta-bar\"><span class=\"badge-subclass\" title=\"Overridden in 11 derived class(es)\">Overridden in 11 subclasses</span></div>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype><tr><td><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">string</span> <span class=\"sv-proto-name\">get_full_name</span> <span class=\"sv-op\">(</span><span class=\"sv-op\">)</span>\n  </td></tr></table></blockquote><div class=CBody><p>Returns the full hierarchical name of this object.&nbsp; The default implementation is the same as <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-7\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-7\" data-target-id=\"doc-nav-item-7\" class=LMethod  >get_name</a>, as uvm_objects do not inherently possess hierarchy.</p><p>Objects possessing hierarchy, such as <a href=\"__ROOT_REL__docs_view/base/uvm_component-svh.html#doc-nav-main\" data-doc-href=\"docs_view/base/uvm_component-svh.html#doc-nav-main\" data-target-id=\"doc-nav-main\" class=LClass  >uvm_components</a>, override the default implementation.&nbsp; Other objects might be associated with component hierarchy but are not themselves components.&nbsp; For example, <a href=\"__ROOT_REL__docs_view/seq/uvm_sequence-svh.html#doc-nav-main\" data-doc-href=\"docs_view/seq/uvm_sequence-svh.html#doc-nav-main\" data-target-id=\"doc-nav-main\" class=LClass  >uvm_sequence #(REQ,RSP)</a> classes are typically associated with a <a href=\"__ROOT_REL__docs_view/seq/uvm_sequencer-svh.html#doc-nav-main\" data-doc-href=\"docs_view/seq/uvm_sequencer-svh.html#doc-nav-main\" data-target-id=\"doc-nav-main\" class=LClass  >uvm_sequencer #(REQ,RSP)</a>.&nbsp; In this case, it is useful to override get_full_name to return the sequencer&rsquo;s full name concatenated with the sequence&rsquo;s name.&nbsp; This provides the sequence a full context, which is useful when debugging.</p></div></div></div>"},{"n":"get_inst_id","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-9","s":"src_view/base/uvm_object.svh.html#L124","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.get_inst_id\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L124\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"124\">get_inst_id</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype><tr><td><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">int</span> <span class=\"sv-proto-name\">get_inst_id</span> <span class=\"sv-op\">(</span><span class=\"sv-op\">)</span>\n  </td></tr></table></blockquote><div class=CBody><p>Returns the object&rsquo;s unique, numeric instance identifier.</p></div></div></div>"},{"n":"get_inst_count","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-10","s":"src_view/base/uvm_object.svh.html#L134","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.get_inst_count\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L134\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"134\">get_inst_count</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype><tr><td><span class=\"sv-qualifier\">static</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">int</span> <span class=\"sv-proto-name\">get_inst_count</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span>\n  </td></tr></table></blockquote><div class=CBody><p>Returns the current value of the instance counter, which represents the total number of uvm_object-based objects that have been allocated in simulation.&nbsp; The instance counter is used to form a unique numeric instance identifier.</p></div></div></div>"},{"n":"get_type","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-11","s":"src_view/base/uvm_object.svh.html#L163","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.get_type\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L163\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"163\">get_type</a></h3><div class=\"method-meta-bar\"><span class=\"badge-subclass\" title=\"Overridden in 2 derived class(es)\">Overridden in 2 subclasses</span></div>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype><tr><td><span class=\"sv-qualifier\">static</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-uvm-type\">uvm_object_wrapper</span> <span class=\"sv-proto-name\">get_type</span> <span class=\"sv-op\">(</span><span class=\"sv-op\">)</span>\n  </td></tr></table></blockquote><div class=CBody><p>Returns the type-proxy (wrapper) for this object.&nbsp; The <a href=\"__ROOT_REL__docs_view/base/uvm_factory-svh.html#doc-nav-item-1\" data-doc-href=\"docs_view/base/uvm_factory-svh.html#doc-nav-item-1\" data-target-id=\"doc-nav-item-1\" class=LClass  >uvm_factory</a>&rsquo;s type-based override and creation methods take arguments of <a href=\"__ROOT_REL__docs_view/base/uvm_factory-svh.html#doc-nav-item-43\" data-doc-href=\"docs_view/base/uvm_factory-svh.html#doc-nav-item-43\" data-target-id=\"doc-nav-item-43\" class=LClass  >uvm_object_wrapper</a>.&nbsp; This method, if implemented, can be used as convenient means of supplying those arguments.</p><p>The default implementation of this method produces an error and returns <i>null</i>.&nbsp; To enable use of this method, a user&rsquo;s subtype must implement a version that returns the subtype&rsquo;s wrapper.</p><h4 class=CHeading>For example</h4><div class=\"code-block-container\">\n  <div class=\"code-block-header\">\n    <div class=\"code-block-lang\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"16 18 22 12 16 6\"/><polyline points=\"8 6 2 12 8 18\"/></svg>\n      <span>SystemVerilog</span>\n    </div>\n    <button class=\"code-copy-btn\" title=\"Copy code\" aria-label=\"Copy code to clipboard\">\n      <svg class=\"copy-icon\" width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre class=\"code-block-content\"><code><span class=\"sv-keyword-decl\">class</span> <span class=\"sv-ident\">cmd</span> <span class=\"sv-keyword-decl\">extends</span> <span class=\"sv-uvm-type\">uvm_object</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-keyword-decl\">typedef</span> <span class=\"sv-uvm-type\">uvm_object_registry</span> <span class=\"sv-op\">#(</span><span class=\"sv-ident\">cmd</span><span class=\"sv-op\">)</span> <span class=\"sv-method\">type_id</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-qualifier\">static</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-method\">type_id</span> <span class=\"sv-method\">get_type</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-keyword\">return</span> <span class=\"sv-method\">type_id</span><span class=\"sv-op\">::</span><span class=\"sv-method\">get</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-keyword-decl\">endfunction</span>\n<span class=\"sv-keyword-decl\">endclass</span></code></pre>\n</div><h4 class=CHeading>Then, to use</h4><div class=\"code-block-container\">\n  <div class=\"code-block-header\">\n    <div class=\"code-block-lang\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"16 18 22 12 16 6\"/><polyline points=\"8 6 2 12 8 18\"/></svg>\n      <span>SystemVerilog</span>\n    </div>\n    <button class=\"code-copy-btn\" title=\"Copy code\" aria-label=\"Copy code to clipboard\">\n      <svg class=\"copy-icon\" width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre class=\"code-block-content\"><code><span class=\"sv-ident\">factory</span><span class=\"sv-op\">.</span><span class=\"sv-method\">set_type_override</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">cmd</span><span class=\"sv-op\">::</span><span class=\"sv-method\">get_type</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">,</span><span class=\"sv-ident\">subcmd</span><span class=\"sv-op\">::</span><span class=\"sv-method\">get_type</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span></code></pre>\n</div><p>This function is implemented by the `uvm_*_utils macros, if employed.</p></div></div></div>"},{"n":"get_object_type","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-12","s":"src_view/base/uvm_object.svh.html#L194","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.get_object_type\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L194\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"194\">get_object_type</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype><tr><td><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-uvm-type\">uvm_object_wrapper</span> <span class=\"sv-proto-name\">get_object_type</span> <span class=\"sv-op\">(</span><span class=\"sv-op\">)</span>\n  </td></tr></table></blockquote><div class=CBody><p>Returns the type-proxy (wrapper) for this object.&nbsp; The <a href=\"__ROOT_REL__docs_view/base/uvm_factory-svh.html#doc-nav-item-1\" data-doc-href=\"docs_view/base/uvm_factory-svh.html#doc-nav-item-1\" data-target-id=\"doc-nav-item-1\" class=LClass  >uvm_factory</a>&rsquo;s type-based override and creation methods take arguments of <a href=\"__ROOT_REL__docs_view/base/uvm_factory-svh.html#doc-nav-item-43\" data-doc-href=\"docs_view/base/uvm_factory-svh.html#doc-nav-item-43\" data-target-id=\"doc-nav-item-43\" class=LClass  >uvm_object_wrapper</a>.&nbsp; This method, if implemented, can be used as convenient means of supplying those arguments.&nbsp; This method is the same as the static <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-11\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-11\" data-target-id=\"doc-nav-item-11\" class=LMethod  >get_type</a> method, but uses an already allocated object to determine the type-proxy to access (instead of using the static object).</p><p>The default implementation of this method does a factory lookup of the proxy using the return value from <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-13\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-13\" data-target-id=\"doc-nav-item-13\" class=LMethod  >get_type_name</a>.&nbsp; If the type returned by <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-13\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-13\" data-target-id=\"doc-nav-item-13\" class=LMethod  >get_type_name</a> is not registered with the factory, then a <i>null</i> handle is returned.</p><h4 class=CHeading>For example</h4><div class=\"code-block-container\">\n  <div class=\"code-block-header\">\n    <div class=\"code-block-lang\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"16 18 22 12 16 6\"/><polyline points=\"8 6 2 12 8 18\"/></svg>\n      <span>SystemVerilog</span>\n    </div>\n    <button class=\"code-copy-btn\" title=\"Copy code\" aria-label=\"Copy code to clipboard\">\n      <svg class=\"copy-icon\" width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre class=\"code-block-content\"><code><span class=\"sv-keyword-decl\">class</span> <span class=\"sv-ident\">cmd</span> <span class=\"sv-keyword-decl\">extends</span> <span class=\"sv-uvm-type\">uvm_object</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-keyword-decl\">typedef</span> <span class=\"sv-uvm-type\">uvm_object_registry</span> <span class=\"sv-op\">#(</span><span class=\"sv-ident\">cmd</span><span class=\"sv-op\">)</span> <span class=\"sv-method\">type_id</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-qualifier\">static</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-method\">type_id</span> <span class=\"sv-method\">get_type</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-keyword\">return</span> <span class=\"sv-method\">type_id</span><span class=\"sv-op\">::</span><span class=\"sv-method\">get</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-keyword-decl\">endfunction</span>\n  <span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-method\">type_id</span> <span class=\"sv-method\">get_object_type</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-keyword\">return</span> <span class=\"sv-method\">type_id</span><span class=\"sv-op\">::</span><span class=\"sv-method\">get</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-keyword-decl\">endfunction</span>\n<span class=\"sv-keyword-decl\">endclass</span></code></pre>\n</div><p>This function is implemented by the `uvm_*_utils macros, if employed.</p></div></div></div>"},{"n":"get_type_name","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-13","s":"src_view/base/uvm_object.svh.html#L220","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.get_type_name\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L220\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"220\">get_type_name</a></h3><div class=\"method-meta-bar\"><span class=\"badge-subclass\" title=\"Overridden in 32 derived class(es)\">Overridden in 32 subclasses</span></div>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype><tr><td><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">string</span> <span class=\"sv-proto-name\">get_type_name</span> <span class=\"sv-op\">(</span><span class=\"sv-op\">)</span>\n  </td></tr></table></blockquote><div class=CBody><p>This function returns the type name of the object, which is typically the type identifier enclosed in quotes.&nbsp; It is used for various debugging functions in the library, and it is used by the factory for creating objects.</p><p>This function must be defined in every derived class.</p><h4 class=CHeading>A typical implementation is as follows</h4><div class=\"code-block-container\">\n  <div class=\"code-block-header\">\n    <div class=\"code-block-lang\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"16 18 22 12 16 6\"/><polyline points=\"8 6 2 12 8 18\"/></svg>\n      <span>SystemVerilog</span>\n    </div>\n    <button class=\"code-copy-btn\" title=\"Copy code\" aria-label=\"Copy code to clipboard\">\n      <svg class=\"copy-icon\" width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre class=\"code-block-content\"><code><span class=\"sv-keyword-decl\">class</span> <span class=\"sv-ident\">mytype</span> <span class=\"sv-keyword-decl\">extends</span> <span class=\"sv-uvm-type\">uvm_object</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-op\">.</span><span class=\"sv-op\">.</span><span class=\"sv-op\">.</span>\n  <span class=\"sv-qualifier\">const</span> <span class=\"sv-qualifier\">static</span> <span class=\"sv-type\">string</span> <span class=\"sv-ident\">type_name</span> <span class=\"sv-op\">=</span> <span class=\"sv-string\">&quot;mytype&quot;</span><span class=\"sv-op\">;</span>\n\n  <span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">string</span> <span class=\"sv-method\">get_type_name</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-keyword\">return</span> <span class=\"sv-ident\">type_name</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-keyword-decl\">endfunction</span></code></pre>\n</div><p>We define the <i>type_name</i> static variable to enable access to the type name without need of an object of the class, i.e., to enable access via the scope operator, <i>mytype::type_name</i>.</p></div></div></div>"},{"n":"create","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-15","s":"src_view/base/uvm_object.svh.html#L240","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.create\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L240\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"240\">create</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-uvm-type\">uvm_object</span> <span class=\"sv-proto-name\">create</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">name</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\">&quot;&quot;</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>The <i>create</i> method allocates a new object of the same type as this object and returns it via a base uvm_object handle.&nbsp; Every class deriving from uvm_object, directly or indirectly, must implement the create method.</p><h4 class=CHeading>A typical implementation is as follows</h4><div class=\"code-block-container\">\n  <div class=\"code-block-header\">\n    <div class=\"code-block-lang\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"16 18 22 12 16 6\"/><polyline points=\"8 6 2 12 8 18\"/></svg>\n      <span>SystemVerilog</span>\n    </div>\n    <button class=\"code-copy-btn\" title=\"Copy code\" aria-label=\"Copy code to clipboard\">\n      <svg class=\"copy-icon\" width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre class=\"code-block-content\"><code><span class=\"sv-keyword-decl\">class</span> <span class=\"sv-ident\">mytype</span> <span class=\"sv-keyword-decl\">extends</span> <span class=\"sv-uvm-type\">uvm_object</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-op\">.</span><span class=\"sv-op\">.</span><span class=\"sv-op\">.</span>\n  <span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-uvm-type\">uvm_object</span> <span class=\"sv-method\">create</span><span class=\"sv-op\">(</span><span class=\"sv-type\">string</span> <span class=\"sv-ident\">name</span><span class=\"sv-op\">=</span><span class=\"sv-string\">&quot;&quot;</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-ident\">mytype</span> <span class=\"sv-ident\">t</span> <span class=\"sv-op\">=</span> <span class=\"sv-method\">new</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">name</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-keyword\">return</span> <span class=\"sv-ident\">t</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-keyword-decl\">endfunction</span></code></pre>\n</div></div></div></div>"},{"n":"clone","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-16","s":"src_view/base/uvm_object.svh.html#L997","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.clone\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L997\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"997\">clone</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype><tr><td><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-uvm-type\">uvm_object</span> <span class=\"sv-proto-name\">clone</span> <span class=\"sv-op\">(</span><span class=\"sv-op\">)</span>\n  </td></tr></table></blockquote><div class=CBody><p>The <i>clone</i> method creates and returns an exact copy of this object.</p><p>The default implementation calls <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-15\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-15\" data-target-id=\"doc-nav-item-15\" class=LMethod  >create</a> followed by <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-26\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-26\" data-target-id=\"doc-nav-item-26\" class=LMethod  >copy</a>.&nbsp; As clone is virtual, derived classes may override this implementation if desired.</p></div></div></div>"},{"n":"print","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-18","s":"src_view/base/uvm_object.svh.html#L876","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.print\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L876\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"876\">print</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-proto-name\">print</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_printer</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">printer</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\">null</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>The <i>print</i> method deep-prints this object&rsquo;s properties in a format and manner governed by the given <i>printer</i> argument; if the <i>printer</i> argument is not provided, the global <a href=\"__ROOT_REL__docs_view/base/uvm_object_globals-svh.html#doc-nav-item-28\" data-doc-href=\"docs_view/base/uvm_object_globals-svh.html#doc-nav-item-28\" data-target-id=\"doc-nav-item-28\" class=LVariable  >uvm_default_printer</a> is used.&nbsp; See <a href=\"__ROOT_REL__docs_view/base/uvm_printer-svh.html#doc-nav-main\" data-doc-href=\"docs_view/base/uvm_printer-svh.html#doc-nav-main\" data-target-id=\"doc-nav-main\" class=LClass  >uvm_printer</a> for more information on printer output formatting.&nbsp; See also <a href=\"__ROOT_REL__docs_view/base/uvm_printer-svh.html#doc-nav-item-29\" data-doc-href=\"docs_view/base/uvm_printer-svh.html#doc-nav-item-29\" data-target-id=\"doc-nav-item-29\" class=LClass  >uvm_line_printer</a>, <a href=\"__ROOT_REL__docs_view/base/uvm_printer-svh.html#doc-nav-item-24\" data-doc-href=\"docs_view/base/uvm_printer-svh.html#doc-nav-item-24\" data-target-id=\"doc-nav-item-24\" class=LClass  >uvm_tree_printer</a>, and <a href=\"__ROOT_REL__docs_view/base/uvm_printer-svh.html#doc-nav-item-19\" data-doc-href=\"docs_view/base/uvm_printer-svh.html#doc-nav-item-19\" data-target-id=\"doc-nav-item-19\" class=LClass  >uvm_table_printer</a> for details on the pre-defined printer &ldquo;policies,&rdquo; or formatters, provided by the UVM.</p><p>The <i>print</i> method is not virtual and must not be overloaded.&nbsp; To include custom information in the <i>print</i> and <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-19\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-19\" data-target-id=\"doc-nav-item-19\" class=LMethod  >sprint</a> operations, derived classes must override the <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-20\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-20\" data-target-id=\"doc-nav-item-20\" class=LMethod  >do_print</a> method and use the provided printer policy class to format the output.</p></div></div></div>"},{"n":"sprint","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-19","s":"src_view/base/uvm_object.svh.html#L888","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.sprint\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L888\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"888\">sprint</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">string</span> <span class=\"sv-proto-name\">sprint</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_printer</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">printer</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\">null</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>The <i>sprint</i> method works just like the <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-18\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-18\" data-target-id=\"doc-nav-item-18\" class=LMethod  >print</a> method, except the output is returned in a string rather than displayed.</p><p>The <i>sprint</i> method is not virtual and must not be overloaded.&nbsp; To include additional fields in the <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-18\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-18\" data-target-id=\"doc-nav-item-18\" class=LMethod  >print</a> and <i>sprint</i> operation, derived classes must override the <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-20\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-20\" data-target-id=\"doc-nav-item-20\" class=LMethod  >do_print</a> method and use the provided printer policy class to format the output.&nbsp; The printer policy will manage all string concatenations and provide the string to <i>sprint</i> to return to the caller.</p></div></div></div>"},{"n":"do_print","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-20","s":"src_view/base/uvm_object.svh.html#L1137","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.do_print\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L1137\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"1137\">do_print</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=3><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-proto-name\">do_print</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_printer</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">printer</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=3><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>The <i>do_print</i> method is the user-definable hook called by <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-18\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-18\" data-target-id=\"doc-nav-item-18\" class=LMethod  >print</a> and <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-19\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-19\" data-target-id=\"doc-nav-item-19\" class=LMethod  >sprint</a> that allows users to customize what gets printed or sprinted beyond the field information provided by the `uvm_field_* macros, <a href=\"__ROOT_REL__docs_view/macros/uvm_object_defines-svh.html#doc-nav-main\" data-doc-href=\"docs_view/macros/uvm_object_defines-svh.html#doc-nav-main\" data-target-id=\"doc-nav-main\" class=LSection >Utility and Field Macros for Components and Objects</a>.</p><p>The <i>printer</i> argument is the policy object that governs the format and content of the output.&nbsp; To ensure correct <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-18\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-18\" data-target-id=\"doc-nav-item-18\" class=LMethod  >print</a> and <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-19\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-19\" data-target-id=\"doc-nav-item-19\" class=LMethod  >sprint</a> operation, and to ensure a consistent output format, the <i>printer</i> must be used by all <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-20\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-20\" data-target-id=\"doc-nav-item-20\" class=LMethod  >do_print</a> implementations.&nbsp; That is, instead of using <i>$display</i> or string concatenations directly, a <i>do_print</i> implementation must call through the <i>printer&rsquo;s</i> API to add information to be printed or sprinted.</p><h4 class=CHeading>An example implementation of <i>do_print</i> is as follows</h4><div class=\"code-block-container\">\n  <div class=\"code-block-header\">\n    <div class=\"code-block-lang\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"16 18 22 12 16 6\"/><polyline points=\"8 6 2 12 8 18\"/></svg>\n      <span>SystemVerilog</span>\n    </div>\n    <button class=\"code-copy-btn\" title=\"Copy code\" aria-label=\"Copy code to clipboard\">\n      <svg class=\"copy-icon\" width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre class=\"code-block-content\"><code><span class=\"sv-keyword-decl\">class</span> <span class=\"sv-ident\">mytype</span> <span class=\"sv-keyword-decl\">extends</span> <span class=\"sv-uvm-type\">uvm_object</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-ident\">data_obj</span> <span class=\"sv-ident\">data</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-type\">int</span> <span class=\"sv-ident\">f1</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-method\">do_print</span> <span class=\"sv-op\">(</span><span class=\"sv-uvm-type\">uvm_printer</span> <span class=\"sv-ident\">printer</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-constant\">super</span><span class=\"sv-op\">.</span><span class=\"sv-method\">do_print</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">printer</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-ident\">printer</span><span class=\"sv-op\">.</span><span class=\"sv-method\">print_field_int</span><span class=\"sv-op\">(</span><span class=\"sv-string\">&quot;f1&quot;</span><span class=\"sv-op\">,</span> <span class=\"sv-ident\">f1</span><span class=\"sv-op\">,</span> <span class=\"sv-system-tf\">$bits</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">f1</span><span class=\"sv-op\">)</span><span class=\"sv-op\">,</span> <span class=\"sv-constant\">UVM_DEC</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-ident\">printer</span><span class=\"sv-op\">.</span><span class=\"sv-method\">print_object</span><span class=\"sv-op\">(</span><span class=\"sv-string\">&quot;data&quot;</span><span class=\"sv-op\">,</span> <span class=\"sv-ident\">data</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-keyword-decl\">endfunction</span></code></pre>\n</div><h4 class=CHeading>Then, to print and sprint the object, you could write</h4><div class=\"code-block-container\">\n  <div class=\"code-block-header\">\n    <div class=\"code-block-lang\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"16 18 22 12 16 6\"/><polyline points=\"8 6 2 12 8 18\"/></svg>\n      <span>SystemVerilog</span>\n    </div>\n    <button class=\"code-copy-btn\" title=\"Copy code\" aria-label=\"Copy code to clipboard\">\n      <svg class=\"copy-icon\" width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre class=\"code-block-content\"><code><span class=\"sv-ident\">mytype</span> <span class=\"sv-ident\">t</span> <span class=\"sv-op\">=</span> <span class=\"sv-ident\">new</span><span class=\"sv-op\">;</span>\n<span class=\"sv-ident\">t</span><span class=\"sv-op\">.</span><span class=\"sv-method\">print</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n<span class=\"sv-uvm-type\">uvm_report_info</span><span class=\"sv-op\">(</span><span class=\"sv-string\">&quot;Received&quot;</span><span class=\"sv-op\">,</span><span class=\"sv-ident\">t</span><span class=\"sv-op\">.</span><span class=\"sv-method\">sprint</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span></code></pre>\n</div><p>See <a href=\"__ROOT_REL__docs_view/base/uvm_printer-svh.html#doc-nav-main\" data-doc-href=\"docs_view/base/uvm_printer-svh.html#doc-nav-main\" data-target-id=\"doc-nav-main\" class=LClass  >uvm_printer</a> for information about the printer API.</p></div></div></div>"},{"n":"convert2string","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-21","s":"src_view/base/uvm_object.svh.html#L916","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.convert2string\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L916\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"916\">convert2string</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype><tr><td><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">string</span> <span class=\"sv-proto-name\">convert2string</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span>\n  </td></tr></table></blockquote><div class=CBody><p>This virtual function is a user-definable hook, called directly by the user, that allows users to provide object information in the form of a string.&nbsp; Unlike <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-19\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-19\" data-target-id=\"doc-nav-item-19\" class=LMethod  >sprint</a>, there is no requirement to use a <a href=\"__ROOT_REL__docs_view/base/uvm_printer-svh.html#doc-nav-main\" data-doc-href=\"docs_view/base/uvm_printer-svh.html#doc-nav-main\" data-target-id=\"doc-nav-main\" class=LClass  >uvm_printer</a> policy object.&nbsp; As such, the format and content of the output is fully customizable, which may be suitable for applications not requiring the consistent formatting offered by the <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-18\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-18\" data-target-id=\"doc-nav-item-18\" class=LMethod  >print</a>/<a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-19\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-19\" data-target-id=\"doc-nav-item-19\" class=LMethod  >sprint</a>/<a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-20\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-20\" data-target-id=\"doc-nav-item-20\" class=LMethod  >do_print</a> API.</p><p>Fields declared in <a href=\"__ROOT_REL__docs_view/macros/uvm_object_defines-svh.html#doc-nav-item-1\" data-doc-href=\"docs_view/macros/uvm_object_defines-svh.html#doc-nav-item-1\" data-target-id=\"doc-nav-item-1\" class=LGroup  >Utility Macros</a> macros (`uvm_field_*), if used, will not automatically appear in calls to convert2string.</p><p>An example implementation of convert2string follows.</p><div class=\"code-block-container\">\n  <div class=\"code-block-header\">\n    <div class=\"code-block-lang\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"16 18 22 12 16 6\"/><polyline points=\"8 6 2 12 8 18\"/></svg>\n      <span>SystemVerilog</span>\n    </div>\n    <button class=\"code-copy-btn\" title=\"Copy code\" aria-label=\"Copy code to clipboard\">\n      <svg class=\"copy-icon\" width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre class=\"code-block-content\"><code><span class=\"sv-keyword-decl\">class</span> <span class=\"sv-ident\">base</span> <span class=\"sv-keyword-decl\">extends</span> <span class=\"sv-uvm-type\">uvm_object</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-type\">string</span> <span class=\"sv-ident\">field</span> <span class=\"sv-op\">=</span> <span class=\"sv-string\">&quot;foo&quot;</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">string</span> <span class=\"sv-method\">convert2string</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-method\">convert2string</span> <span class=\"sv-op\">=</span> <span class=\"sv-op\">{</span><span class=\"sv-string\">&quot;base_field=&quot;</span><span class=\"sv-op\">,</span><span class=\"sv-ident\">field</span><span class=\"sv-op\">}</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-keyword-decl\">endfunction</span>\n<span class=\"sv-keyword-decl\">endclass</span>\n\n<span class=\"sv-keyword-decl\">class</span> <span class=\"sv-ident\">obj2</span> <span class=\"sv-keyword-decl\">extends</span> <span class=\"sv-uvm-type\">uvm_object</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-type\">string</span> <span class=\"sv-ident\">field</span> <span class=\"sv-op\">=</span> <span class=\"sv-string\">&quot;bar&quot;</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">string</span> <span class=\"sv-method\">convert2string</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-method\">convert2string</span> <span class=\"sv-op\">=</span> <span class=\"sv-op\">{</span><span class=\"sv-string\">&quot;child_field=&quot;</span><span class=\"sv-op\">,</span><span class=\"sv-ident\">field</span><span class=\"sv-op\">}</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-keyword-decl\">endfunction</span>\n<span class=\"sv-keyword-decl\">endclass</span>\n\n<span class=\"sv-keyword-decl\">class</span> <span class=\"sv-ident\">obj</span> <span class=\"sv-keyword-decl\">extends</span> <span class=\"sv-ident\">base</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-type\">int</span> <span class=\"sv-ident\">addr</span> <span class=\"sv-op\">=</span> <span class=\"sv-number\">&#x27;h123</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-type\">int</span> <span class=\"sv-ident\">data</span> <span class=\"sv-op\">=</span> <span class=\"sv-number\">&#x27;h456</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-type\">bit</span> <span class=\"sv-method\">write</span> <span class=\"sv-op\">=</span> <span class=\"sv-number\">1</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-ident\">obj2</span> <span class=\"sv-ident\">child</span> <span class=\"sv-op\">=</span> <span class=\"sv-ident\">new</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">string</span> <span class=\"sv-method\">convert2string</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n     <span class=\"sv-method\">convert2string</span> <span class=\"sv-op\">=</span> <span class=\"sv-op\">{</span><span class=\"sv-constant\">super</span><span class=\"sv-op\">.</span><span class=\"sv-method\">convert2string</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">,</span>\n       <span class=\"sv-system-tf\">$sformatf</span><span class=\"sv-op\">(</span><span class=\"sv-string\">&quot; write=<span class=\"sv-string-escape\">%0d</span> addr=<span class=\"sv-string-escape\">%8h</span> data=<span class=\"sv-string-escape\">%8h</span> &quot;</span><span class=\"sv-op\">,</span><span class=\"sv-method\">write</span><span class=\"sv-op\">,</span><span class=\"sv-ident\">addr</span><span class=\"sv-op\">,</span><span class=\"sv-ident\">data</span><span class=\"sv-op\">)</span><span class=\"sv-op\">,</span>\n       <span class=\"sv-ident\">child</span><span class=\"sv-op\">.</span><span class=\"sv-method\">convert2string</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">}</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-keyword-decl\">endfunction</span>\n<span class=\"sv-keyword-decl\">endclass</span></code></pre>\n</div><h4 class=CHeading>Then, to display an object, you could write</h4><div class=\"code-block-container\">\n  <div class=\"code-block-header\">\n    <div class=\"code-block-lang\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"16 18 22 12 16 6\"/><polyline points=\"8 6 2 12 8 18\"/></svg>\n      <span>SystemVerilog</span>\n    </div>\n    <button class=\"code-copy-btn\" title=\"Copy code\" aria-label=\"Copy code to clipboard\">\n      <svg class=\"copy-icon\" width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre class=\"code-block-content\"><code><span class=\"sv-ident\">obj</span> <span class=\"sv-ident\">o</span> <span class=\"sv-op\">=</span> <span class=\"sv-ident\">new</span><span class=\"sv-op\">;</span>\n<span class=\"sv-uvm-type\">uvm_report_info</span><span class=\"sv-op\">(</span><span class=\"sv-string\">&quot;BusMaster&quot;</span><span class=\"sv-op\">,</span><span class=\"sv-op\">{</span><span class=\"sv-string\">&quot;Sending:<span class=\"sv-string-escape\">\\n</span> &quot;</span><span class=\"sv-op\">,</span><span class=\"sv-ident\">o</span><span class=\"sv-op\">.</span><span class=\"sv-method\">convert2string</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">}</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span></code></pre>\n</div><h4 class=CHeading>The output will look similar to</h4><div class=\"code-block-container\">\n  <div class=\"code-block-header\">\n    <div class=\"code-block-lang\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"16 18 22 12 16 6\"/><polyline points=\"8 6 2 12 8 18\"/></svg>\n      <span>SystemVerilog</span>\n    </div>\n    <button class=\"code-copy-btn\" title=\"Copy code\" aria-label=\"Copy code to clipboard\">\n      <svg class=\"copy-icon\" width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre class=\"code-block-content\"><code><span class=\"sv-constant\">UVM_INFO</span> @ <span class=\"sv-number\">0</span><span class=\"sv-op\">:</span> <span class=\"sv-ident\">reporter</span> <span class=\"sv-op\">[</span><span class=\"sv-ident\">BusMaster</span><span class=\"sv-op\">]</span> <span class=\"sv-ident\">Sending</span><span class=\"sv-op\">:</span>\n   <span class=\"sv-ident\">base_field</span><span class=\"sv-op\">=</span><span class=\"sv-ident\">foo</span> <span class=\"sv-method\">write</span><span class=\"sv-op\">=</span><span class=\"sv-number\">1</span> <span class=\"sv-ident\">addr</span><span class=\"sv-op\">=</span><span class=\"sv-number\">00000123</span> <span class=\"sv-ident\">data</span><span class=\"sv-op\">=</span><span class=\"sv-number\">00000456</span> <span class=\"sv-ident\">child_field</span><span class=\"sv-op\">=</span><span class=\"sv-ident\">bar</span></code></pre>\n</div></div></div></div>"},{"n":"record","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-23","s":"src_view/base/uvm_object.svh.html#L1295","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.record\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L1295\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"1295\">record</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-proto-name\">record</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_recorder</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">recorder</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\">null</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>The <i>record</i> method deep-records this object&rsquo;s properties according to an optional <i>recorder</i> policy.&nbsp; The method is not virtual and must not be overloaded.&nbsp; To include additional fields in the record operation, derived classes should override the <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-24\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-24\" data-target-id=\"doc-nav-item-24\" class=LMethod  >do_record</a> method.</p><p>The optional <i>recorder</i> argument specifies the recording policy, which governs how recording takes place.&nbsp; See <a href=\"__ROOT_REL__docs_view/base/uvm_recorder-svh.html#doc-nav-item-1\" data-doc-href=\"docs_view/base/uvm_recorder-svh.html#doc-nav-item-1\" data-target-id=\"doc-nav-item-1\" class=LClass  >uvm_recorder</a> for information.</p><p>A simulator&rsquo;s recording mechanism is vendor-specific.&nbsp; By providing access via a common interface, the uvm_recorder policy provides vendor-independent access to a simulator&rsquo;s recording capabilities.</p></div></div></div>"},{"n":"do_record","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-24","s":"src_view/base/uvm_object.svh.html#L1319","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.do_record\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L1319\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"1319\">do_record</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=3><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-proto-name\">do_record</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_recorder</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">recorder</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=3><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>The <i>do_record</i> method is the user-definable hook called by the <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-23\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-23\" data-target-id=\"doc-nav-item-23\" class=LMethod  >record</a> method.&nbsp; A derived class should override this method to include its fields in a record operation.</p><p>The <i>recorder</i> argument is policy object for recording this object.&nbsp; A do_record implementation should call the appropriate recorder methods for each of its fields.&nbsp; Vendor-specific recording implementations are encapsulated in the <i>recorder</i> policy, thereby insulating user-code from vendor-specific behavior.&nbsp; See <a href=\"__ROOT_REL__docs_view/base/uvm_recorder-svh.html#doc-nav-item-1\" data-doc-href=\"docs_view/base/uvm_recorder-svh.html#doc-nav-item-1\" data-target-id=\"doc-nav-item-1\" class=LClass  >uvm_recorder</a> for more information.</p><h4 class=CHeading>A typical implementation is as follows</h4><div class=\"code-block-container\">\n  <div class=\"code-block-header\">\n    <div class=\"code-block-lang\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"16 18 22 12 16 6\"/><polyline points=\"8 6 2 12 8 18\"/></svg>\n      <span>SystemVerilog</span>\n    </div>\n    <button class=\"code-copy-btn\" title=\"Copy code\" aria-label=\"Copy code to clipboard\">\n      <svg class=\"copy-icon\" width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre class=\"code-block-content\"><code><span class=\"sv-keyword-decl\">class</span> <span class=\"sv-ident\">mytype</span> <span class=\"sv-keyword-decl\">extends</span> <span class=\"sv-uvm-type\">uvm_object</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-ident\">data_obj</span> <span class=\"sv-ident\">data</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-type\">int</span> <span class=\"sv-ident\">f1</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-method\">do_record</span> <span class=\"sv-op\">(</span><span class=\"sv-uvm-type\">uvm_recorder</span> <span class=\"sv-ident\">recorder</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-ident\">recorder</span><span class=\"sv-op\">.</span><span class=\"sv-method\">record_field</span><span class=\"sv-op\">(</span><span class=\"sv-string\">&quot;f1&quot;</span><span class=\"sv-op\">,</span> <span class=\"sv-ident\">f1</span><span class=\"sv-op\">,</span> <span class=\"sv-system-tf\">$bits</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">f1</span><span class=\"sv-op\">)</span><span class=\"sv-op\">,</span> <span class=\"sv-constant\">UVM_DEC</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-ident\">recorder</span><span class=\"sv-op\">.</span><span class=\"sv-method\">record_object</span><span class=\"sv-op\">(</span><span class=\"sv-string\">&quot;data&quot;</span><span class=\"sv-op\">,</span> <span class=\"sv-ident\">data</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-keyword-decl\">endfunction</span></code></pre>\n</div></div></div></div>"},{"n":"copy","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-26","s":"src_view/base/uvm_object.svh.html#L1011","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.copy\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L1011\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"1011\">copy</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=3><span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-proto-name\">copy</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_object</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">rhs</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=3><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>The copy makes this object a copy of the specified object.</p><p>The <i>copy</i> method is not virtual and should not be overloaded in derived classes.&nbsp; To copy the fields of a derived class, that class should override the <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-27\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-27\" data-target-id=\"doc-nav-item-27\" class=LMethod  >do_copy</a> method.</p></div></div></div>"},{"n":"do_copy","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-27","s":"src_view/base/uvm_object.svh.html#L1039","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.do_copy\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L1039\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"1039\">do_copy</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=3><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-proto-name\">do_copy</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_object</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">rhs</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=3><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>The <i>do_copy</i> method is the user-definable hook called by the <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-26\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-26\" data-target-id=\"doc-nav-item-26\" class=LMethod  >copy</a> method.&nbsp; A derived class should override this method to include its fields in a <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-26\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-26\" data-target-id=\"doc-nav-item-26\" class=LMethod  >copy</a> operation.</p><h4 class=CHeading>A typical implementation is as follows</h4><div class=\"code-block-container\">\n  <div class=\"code-block-header\">\n    <div class=\"code-block-lang\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"16 18 22 12 16 6\"/><polyline points=\"8 6 2 12 8 18\"/></svg>\n      <span>SystemVerilog</span>\n    </div>\n    <button class=\"code-copy-btn\" title=\"Copy code\" aria-label=\"Copy code to clipboard\">\n      <svg class=\"copy-icon\" width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre class=\"code-block-content\"><code><span class=\"sv-keyword-decl\">class</span> <span class=\"sv-ident\">mytype</span> <span class=\"sv-keyword-decl\">extends</span> <span class=\"sv-uvm-type\">uvm_object</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-op\">.</span><span class=\"sv-op\">.</span><span class=\"sv-op\">.</span>\n  <span class=\"sv-type\">int</span> <span class=\"sv-ident\">f1</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-method\">do_copy</span> <span class=\"sv-op\">(</span><span class=\"sv-uvm-type\">uvm_object</span> <span class=\"sv-ident\">rhs</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-ident\">mytype</span> <span class=\"sv-ident\">rhs_</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-constant\">super</span><span class=\"sv-op\">.</span><span class=\"sv-method\">do_copy</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">rhs</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-system-tf\">$cast</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">rhs_</span><span class=\"sv-op\">,</span><span class=\"sv-ident\">rhs</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-ident\">field_1</span> <span class=\"sv-op\">=</span> <span class=\"sv-ident\">rhs_</span><span class=\"sv-op\">.</span><span class=\"sv-ident\">field_1</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-keyword-decl\">endfunction</span></code></pre>\n</div><p>The implementation must call <i>super.do_copy</i>, and it must $cast the rhs argument to the derived type before copying.</p></div></div></div>"},{"n":"compare","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-29","s":"src_view/base/uvm_object.svh.html#L1047","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.compare\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L1047\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"1047\">compare</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">bit</span> <span class=\"sv-proto-name\">compare</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_object</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">rhs</span><span class=\"sv-op\">,</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_comparer</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">comparer</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\">null</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>Deep compares members of this data object with those of the object provided in the <i>rhs</i> (right-hand side) argument, returning 1 on a match, 0 otherwise.</p><p>The <i>compare</i> method is not virtual and should not be overloaded in derived classes.&nbsp; To compare the fields of a derived class, that class should override the <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-30\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-30\" data-target-id=\"doc-nav-item-30\" class=LMethod  >do_compare</a> method.</p><p>The optional <i>comparer</i> argument specifies the comparison policy.&nbsp; It allows you to control some aspects of the comparison operation.&nbsp; It also stores the results of the comparison, such as field-by-field miscompare information and the total number of miscompares.&nbsp; If a compare policy is not provided, then the global <i>uvm_default_comparer</i> policy is used.&nbsp; See <a href=\"__ROOT_REL__docs_view/base/uvm_comparer-svh.html#doc-nav-main\" data-doc-href=\"docs_view/base/uvm_comparer-svh.html#doc-nav-main\" data-target-id=\"doc-nav-main\" class=LClass  >uvm_comparer</a> for more information.</p></div></div></div>"},{"n":"do_compare","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-30","s":"src_view/base/uvm_object.svh.html#L1117","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.do_compare\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L1117\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"1117\">do_compare</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=3><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">bit</span> <span class=\"sv-proto-name\">do_compare</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_object</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">rhs</span><span class=\"sv-op\">,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_comparer</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">comparer</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=3><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>The <i>do_compare</i> method is the user-definable hook called by the <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-29\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-29\" data-target-id=\"doc-nav-item-29\" class=LMethod  >compare</a> method.&nbsp; A derived class should override this method to include its fields in a compare operation.&nbsp; It should return 1 if the comparison succeeds, 0 otherwise.</p><h4 class=CHeading>A typical implementation is as follows</h4><div class=\"code-block-container\">\n  <div class=\"code-block-header\">\n    <div class=\"code-block-lang\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"16 18 22 12 16 6\"/><polyline points=\"8 6 2 12 8 18\"/></svg>\n      <span>SystemVerilog</span>\n    </div>\n    <button class=\"code-copy-btn\" title=\"Copy code\" aria-label=\"Copy code to clipboard\">\n      <svg class=\"copy-icon\" width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre class=\"code-block-content\"><code><span class=\"sv-keyword-decl\">class</span> <span class=\"sv-ident\">mytype</span> <span class=\"sv-keyword-decl\">extends</span> <span class=\"sv-uvm-type\">uvm_object</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-op\">.</span><span class=\"sv-op\">.</span><span class=\"sv-op\">.</span>\n  <span class=\"sv-type\">int</span> <span class=\"sv-ident\">f1</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">bit</span> <span class=\"sv-method\">do_compare</span> <span class=\"sv-op\">(</span><span class=\"sv-uvm-type\">uvm_object</span> <span class=\"sv-ident\">rhs</span><span class=\"sv-op\">,</span><span class=\"sv-uvm-type\">uvm_comparer</span> <span class=\"sv-ident\">comparer</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-ident\">mytype</span> <span class=\"sv-ident\">rhs_</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-method\">do_compare</span> <span class=\"sv-op\">=</span> <span class=\"sv-constant\">super</span><span class=\"sv-op\">.</span><span class=\"sv-method\">do_compare</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">rhs</span><span class=\"sv-op\">,</span><span class=\"sv-ident\">comparer</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-system-tf\">$cast</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">rhs_</span><span class=\"sv-op\">,</span><span class=\"sv-ident\">rhs</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-method\">do_compare</span> <span class=\"sv-op\">&amp;=</span> <span class=\"sv-ident\">comparer</span><span class=\"sv-op\">.</span><span class=\"sv-method\">compare_field_int</span><span class=\"sv-op\">(</span><span class=\"sv-string\">&quot;f1&quot;</span><span class=\"sv-op\">,</span> <span class=\"sv-ident\">f1</span><span class=\"sv-op\">,</span> <span class=\"sv-ident\">rhs_</span><span class=\"sv-op\">.</span><span class=\"sv-ident\">f1</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-keyword-decl\">endfunction</span></code></pre>\n</div><p>A derived class implementation must call <i>super.do_compare()</i> to ensure its base class&rsquo; properties, if any, are included in the comparison.&nbsp; Also, the rhs argument is provided as a generic uvm_object.&nbsp; Thus, you must <i>$cast</i> it to the type of this object before comparing.</p><p>The actual comparison should be implemented using the uvm_comparer object rather than direct field-by-field comparison.&nbsp; This enables users of your class to customize how comparisons are performed and how much miscompare information is collected.&nbsp; See uvm_comparer for more details.</p></div></div></div>"},{"n":"pack","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-32","s":"src_view/base/uvm_object.svh.html#L1169","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.pack\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L1169\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"1169\">pack</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=6><span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">int</span> <span class=\"sv-proto-name\">pack</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">ref</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">bit</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">bitstream</span>[],</td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_packer</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">packer</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\">null</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=6><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody></div></div></div>"},{"n":"pack_bytes","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-33","s":"src_view/base/uvm_object.svh.html#L1179","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.pack_bytes\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L1179\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"1179\">pack_bytes</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=6><span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">int</span> <span class=\"sv-proto-name\">pack_bytes</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">ref</span> <span class=\"sv-type\">byte</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">unsigned</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">bytestream</span>[],</td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_packer</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">packer</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\">null</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=6><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody></div></div></div>"},{"n":"pack_ints","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-34","s":"src_view/base/uvm_object.svh.html#L1190","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.pack_ints\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L1190\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"1190\">pack_ints</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=6><span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">int</span> <span class=\"sv-proto-name\">pack_ints</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">ref</span> <span class=\"sv-type\">int</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">unsigned</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">intstream</span>[],</td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_packer</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">packer</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\">null</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=6><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>The pack methods bitwise-concatenate this object&rsquo;s properties into an array of bits, bytes, or ints.&nbsp; The methods are not virtual and must not be overloaded.&nbsp; To include additional fields in the pack operation, derived classes should override the <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-35\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-35\" data-target-id=\"doc-nav-item-35\" class=LMethod  >do_pack</a> method.</p><p>The optional <i>packer</i> argument specifies the packing policy, which governs the packing operation.&nbsp; If a packer policy is not provided, the global <a href=\"__ROOT_REL__docs_view/base/uvm_object_globals-svh.html#doc-nav-item-29\" data-doc-href=\"docs_view/base/uvm_object_globals-svh.html#doc-nav-item-29\" data-target-id=\"doc-nav-item-29\" class=LVariable  >uvm_default_packer</a> policy is used.&nbsp; See <a href=\"__ROOT_REL__docs_view/base/uvm_packer-svh.html#doc-nav-main\" data-doc-href=\"docs_view/base/uvm_packer-svh.html#doc-nav-main\" data-target-id=\"doc-nav-main\" class=LClass  >uvm_packer</a> for more information.</p><p>The return value is the total number of bits packed into the given array.&nbsp; Use the array&rsquo;s built-in <i>size</i> method to get the number of bytes or ints consumed during the packing process.</p></div></div></div>"},{"n":"do_pack","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-35","s":"src_view/base/uvm_object.svh.html#L1201","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.do_pack\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L1201\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"1201\">do_pack</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=3><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-proto-name\">do_pack</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_packer</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">packer</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=3><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>The <i>do_pack</i> method is the user-definable hook called by the <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-32\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-32\" data-target-id=\"doc-nav-item-32\" class=LMethod  >pack</a> methods.&nbsp; A derived class should override this method to include its fields in a pack operation.</p><p>The <i>packer</i> argument is the policy object for packing.&nbsp; The policy object should be used to pack objects.</p><p>A typical example of an object packing itself is as follows</p><div class=\"code-block-container\">\n  <div class=\"code-block-header\">\n    <div class=\"code-block-lang\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"16 18 22 12 16 6\"/><polyline points=\"8 6 2 12 8 18\"/></svg>\n      <span>SystemVerilog</span>\n    </div>\n    <button class=\"code-copy-btn\" title=\"Copy code\" aria-label=\"Copy code to clipboard\">\n      <svg class=\"copy-icon\" width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre class=\"code-block-content\"><code><span class=\"sv-keyword-decl\">class</span> <span class=\"sv-ident\">mysubtype</span> <span class=\"sv-keyword-decl\">extends</span> <span class=\"sv-ident\">mysupertype</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-op\">.</span><span class=\"sv-op\">.</span><span class=\"sv-op\">.</span>\n  <span class=\"sv-type\">shortint</span> <span class=\"sv-ident\">myshort</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-ident\">obj_type</span> <span class=\"sv-ident\">myobj</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-type\">byte</span> <span class=\"sv-ident\">myarray</span><span class=\"sv-op\">[</span><span class=\"sv-op\">]</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-op\">.</span><span class=\"sv-op\">.</span><span class=\"sv-op\">.</span>\n  <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-method\">do_pack</span> <span class=\"sv-op\">(</span><span class=\"sv-uvm-type\">uvm_packer</span> <span class=\"sv-ident\">packer</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-constant\">super</span><span class=\"sv-op\">.</span><span class=\"sv-method\">do_pack</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">packer</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span> <span class=\"sv-comment\">// pack mysupertype properties</span>\n    <span class=\"sv-ident\">packer</span><span class=\"sv-op\">.</span><span class=\"sv-method\">pack_field_int</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">myarray</span><span class=\"sv-op\">.</span><span class=\"sv-method\">size</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">,</span> <span class=\"sv-number\">32</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-keyword\">foreach</span> <span class=\"sv-op\">(</span><span class=\"sv-ident\">myarray</span><span class=\"sv-op\">)</span>\n      <span class=\"sv-ident\">packer</span><span class=\"sv-op\">.</span><span class=\"sv-method\">pack_field_int</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">myarray</span><span class=\"sv-op\">[</span><span class=\"sv-ident\">index</span><span class=\"sv-op\">]</span><span class=\"sv-op\">,</span> <span class=\"sv-number\">8</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-ident\">packer</span><span class=\"sv-op\">.</span><span class=\"sv-method\">pack_field_int</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">myshort</span><span class=\"sv-op\">,</span> <span class=\"sv-system-tf\">$bits</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">myshort</span><span class=\"sv-op\">)</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-ident\">packer</span><span class=\"sv-op\">.</span><span class=\"sv-method\">pack_object</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">myobj</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-keyword-decl\">endfunction</span></code></pre>\n</div><p>The implementation must call <i>super.do_pack</i> so that base class properties are packed as well.</p><p>If your object contains dynamic data (object, string, queue, dynamic array, or associative array), and you intend to unpack into an equivalent data structure when unpacking, you must include meta-information about the dynamic data when packing as follows.</p><ul><li>For queues, dynamic arrays, or associative arrays, pack the number of elements in the array in the 32 bits immediately before packing individual elements, as shown above.</li><li>For string data types, append a zero byte after packing the string contents.</li><li>For objects, pack 4 bits immediately before packing the object.&nbsp; For <i>null</i> objects, pack 4&rsquo;b0000.&nbsp; For non-<i>null</i> objects, pack 4&rsquo;b0001.</li></ul><p>When the `uvm_field_* macros are used, <a href=\"__ROOT_REL__docs_view/macros/uvm_object_defines-svh.html#doc-nav-main\" data-doc-href=\"docs_view/macros/uvm_object_defines-svh.html#doc-nav-main\" data-target-id=\"doc-nav-main\" class=LSection >Utility and Field Macros for Components and Objects</a>, the above meta information is included provided the <a href=\"__ROOT_REL__docs_view/base/uvm_packer-svh.html#doc-nav-item-26\" data-doc-href=\"docs_view/base/uvm_packer-svh.html#doc-nav-item-26\" data-target-id=\"doc-nav-item-26\" class=LVariable  >uvm_packer::use_metadata</a> variable is set for the packer.</p><p>Packing order does not need to match declaration order.&nbsp; However, unpacking order must match packing order.</p></div></div></div>"},{"n":"unpack","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-37","s":"src_view/base/uvm_object.svh.html#L1248","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.unpack\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L1248\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"1248\">unpack</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=6><span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">int</span> <span class=\"sv-proto-name\">unpack</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">ref</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">bit</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">bitstream</span>[],</td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_packer</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">packer</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\">null</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=6><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody></div></div></div>"},{"n":"unpack_bytes","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-38","s":"src_view/base/uvm_object.svh.html#L1261","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.unpack_bytes\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L1261\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"1261\">unpack_bytes</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=6><span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">int</span> <span class=\"sv-proto-name\">unpack_bytes</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">ref</span> <span class=\"sv-type\">byte</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">unsigned</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">bytestream</span>[],</td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_packer</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">packer</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\">null</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=6><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody></div></div></div>"},{"n":"unpack_ints","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-39","s":"src_view/base/uvm_object.svh.html#L1274","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.unpack_ints\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L1274\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"1274\">unpack_ints</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=6><span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">int</span> <span class=\"sv-proto-name\">unpack_ints</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">ref</span> <span class=\"sv-type\">int</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-type\">unsigned</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">intstream</span>[],</td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PTypePrefix nowrap><span class=\"sv-qualifier\">input</span>&nbsp;</td>\n      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_packer</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">packer</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\">null</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=6><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>The unpack methods extract property values from an array of bits, bytes, or ints.&nbsp; The method of unpacking <i>must</i> exactly correspond to the method of packing.&nbsp; This is assured if (a) the same <i>packer</i> policy is used to pack and unpack, and (b) the order of unpacking is the same as the order of packing used to create the input array.</p><p>The unpack methods are fixed (non-virtual) entry points that are directly callable by the user.&nbsp; To include additional fields in the <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-37\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-37\" data-target-id=\"doc-nav-item-37\" class=LMethod  >unpack</a> operation, derived classes should override the <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-40\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-40\" data-target-id=\"doc-nav-item-40\" class=LMethod  >do_unpack</a> method.</p><p>The optional <i>packer</i> argument specifies the packing policy, which governs both the pack and unpack operation.&nbsp; If a packer policy is not provided, then the global <i>uvm_default_packer</i> policy is used.&nbsp; See uvm_packer for more information.</p><p>The return value is the actual number of bits unpacked from the given array.</p></div></div></div>"},{"n":"do_unpack","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-40","s":"src_view/base/uvm_object.svh.html#L1287","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.do_unpack\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L1287\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"1287\">do_unpack</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=3><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-proto-name\">do_unpack</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_packer</span>&nbsp;</td>\n      <td class=PParameter nowrap width=100%><span class=\"sv-param-name\">packer</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=3><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>The <i>do_unpack</i> method is the user-definable hook called by the <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-37\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-37\" data-target-id=\"doc-nav-item-37\" class=LMethod  >unpack</a> method.&nbsp; A derived class should override this method to include its fields in an unpack operation.</p><p>The <i>packer</i> argument is the policy object for both packing and unpacking.&nbsp; It must be the same packer used to pack the object into bits.&nbsp; Also, do_unpack must unpack fields in the same order in which they were packed.&nbsp; See <a href=\"__ROOT_REL__docs_view/base/uvm_packer-svh.html#doc-nav-main\" data-doc-href=\"docs_view/base/uvm_packer-svh.html#doc-nav-main\" data-target-id=\"doc-nav-main\" class=LClass  >uvm_packer</a> for more information.</p><p>The following implementation corresponds to the example given in do_pack.</p><div class=\"code-block-container\">\n  <div class=\"code-block-header\">\n    <div class=\"code-block-lang\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"16 18 22 12 16 6\"/><polyline points=\"8 6 2 12 8 18\"/></svg>\n      <span>SystemVerilog</span>\n    </div>\n    <button class=\"code-copy-btn\" title=\"Copy code\" aria-label=\"Copy code to clipboard\">\n      <svg class=\"copy-icon\" width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre class=\"code-block-content\"><code><span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-method\">do_unpack</span> <span class=\"sv-op\">(</span><span class=\"sv-uvm-type\">uvm_packer</span> <span class=\"sv-ident\">packer</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n <span class=\"sv-type\">int</span> <span class=\"sv-ident\">sz</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-constant\">super</span><span class=\"sv-op\">.</span><span class=\"sv-method\">do_unpack</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">packer</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span> <span class=\"sv-comment\">// unpack super&#x27;s properties</span>\n  <span class=\"sv-ident\">sz</span> <span class=\"sv-op\">=</span> <span class=\"sv-ident\">packer</span><span class=\"sv-op\">.</span><span class=\"sv-method\">unpack_field_int</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">myarray</span><span class=\"sv-op\">.</span><span class=\"sv-method\">size</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">,</span> <span class=\"sv-number\">32</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-ident\">myarray</span><span class=\"sv-op\">.</span><span class=\"sv-method\">delete</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-keyword\">for</span><span class=\"sv-op\">(</span><span class=\"sv-type\">int</span> <span class=\"sv-ident\">index</span><span class=\"sv-op\">=</span><span class=\"sv-number\">0</span><span class=\"sv-op\">;</span> <span class=\"sv-ident\">index</span><span class=\"sv-op\">&lt;</span><span class=\"sv-ident\">sz</span><span class=\"sv-op\">;</span> <span class=\"sv-ident\">index</span><span class=\"sv-op\">++</span><span class=\"sv-op\">)</span>\n    <span class=\"sv-ident\">myarray</span><span class=\"sv-op\">[</span><span class=\"sv-ident\">index</span><span class=\"sv-op\">]</span> <span class=\"sv-op\">=</span> <span class=\"sv-ident\">packer</span><span class=\"sv-op\">.</span><span class=\"sv-method\">unpack_field_int</span><span class=\"sv-op\">(</span><span class=\"sv-number\">8</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-ident\">myshort</span> <span class=\"sv-op\">=</span> <span class=\"sv-ident\">packer</span><span class=\"sv-op\">.</span><span class=\"sv-method\">unpack_field_int</span><span class=\"sv-op\">(</span><span class=\"sv-system-tf\">$bits</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">myshort</span><span class=\"sv-op\">)</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-ident\">packer</span><span class=\"sv-op\">.</span><span class=\"sv-method\">unpack_object</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">myobj</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n<span class=\"sv-keyword-decl\">endfunction</span></code></pre>\n</div><p>If your object contains dynamic data (object, string, queue, dynamic array, or associative array), and you intend to <a href=\"__ROOT_REL__docs_view/base/uvm_object-svh.html#doc-nav-item-37\" data-doc-href=\"docs_view/base/uvm_object-svh.html#doc-nav-item-37\" data-target-id=\"doc-nav-item-37\" class=LMethod  >unpack</a> into an equivalent data structure, you must have included meta-information about the dynamic data when it was packed.</p><ul><li>For queues, dynamic arrays, or associative arrays, unpack the number of elements in the array from the 32 bits immediately before unpacking individual elements, as shown above.</li><li>For string data types, unpack into the new string until a <i>null</i> byte is encountered.</li><li>For objects, unpack 4 bits into a byte or int variable.&nbsp; If the value is 0, the target object should be set to <i>null</i> and unpacking continues to the next property, if any.&nbsp; If the least significant bit is 1, then the target object should be allocated and its properties unpacked.</li></ul></div></div></div>"},{"n":"set_int_local","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-42","s":"src_view/base/uvm_object.svh.html#L924","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.set_int_local\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L924\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"924\">set_int_local</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-proto-name\">set_int_local</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">field_name</span><span class=\"sv-op\">,</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_bitstream_t</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">value</span><span class=\"sv-op\">,</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">bit</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">recurse</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\">1</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody></div></div></div>"},{"n":"set_string_local","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-43","s":"src_view/base/uvm_object.svh.html#L975","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.set_string_local\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L975\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"975\">set_string_local</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-proto-name\">set_string_local</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">field_name</span><span class=\"sv-op\">,</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">value</span><span class=\"sv-op\">,</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">bit</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">recurse</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\">1</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody></div></div></div>"},{"n":"set_object_local","k":"method","d":"docs_view/base/uvm_object-svh.html#doc-nav-item-44","s":"src_view/base/uvm_object.svh.html#L945","h":"<div class=\"CMethod\" data-anchor=\"uvm_object.set_object_local\"><div class=\"CTopic\"><h3 class=CTitle><a href=\"__ROOT_REL__src_view/base/uvm_object.svh.html#L945\" class=\"src-code-link\" data-src-file=\"base/uvm_object.svh\" data-src-line=\"945\">set_object_local</a></h3>\n    <blockquote><table border=0 cellspacing=0 cellpadding=0 class=Prototype>\n      <tr><td><table border=0 cellspacing=0 cellpadding=0><tr>\n      <td class=PBeforeParameters colspan=5><span class=\"sv-qualifier\">virtual</span> <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-proto-name\">set_object_local</span> <span class=\"sv-op\">(</span></td>      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">string</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">field_name</span><span class=\"sv-op\">,</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-uvm-type\">uvm_object</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">value</span><span class=\"sv-op\">,</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\"></span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">bit</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">clone</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\">1,</span></td>\n      </tr><tr><td>&nbsp;&nbsp;&nbsp;</td>      <td class=PType nowrap><span class=\"sv-type\">bit</span>&nbsp;</td>\n      <td class=PParameter nowrap><span class=\"sv-param-name\">recurse</span></td>\n      <td class=PDefaultValuePrefix><span class=\"sv-op\">&nbsp;=&nbsp;</span></td>\n      <td class=PDefaultValue width=100%><span class=\"sv-default-val\">1</span></td>\n    </tr>\n    <tr>\n      <td class=PAfterParameters colspan=5><span class=\"sv-op\">)</span></td></tr>\n      </table></td></tr>\n    </table></blockquote>\n<div class=CBody><p>These methods provide write access to integral, string, and uvm_object-based properties indexed by a <i>field_name</i> string.&nbsp; The object designer choose which, if any, properties will be accessible, and overrides the appropriate methods depending on the properties&rsquo; types.&nbsp; For objects, the optional <i>clone</i> argument specifies whether to clone the <i>value</i> argument before assignment.</p><p>The global <a href=\"__ROOT_REL__docs_view/base/uvm_globals-svh.html#doc-nav-item-13\" data-doc-href=\"docs_view/base/uvm_globals-svh.html#doc-nav-item-13\" data-target-id=\"doc-nav-item-13\" class=LMethod  >uvm_is_match</a> function is used to match the field names, so <i>field_name</i> may contain wildcards.</p><p>An example implementation of all three methods is as follows.</p><div class=\"code-block-container\">\n  <div class=\"code-block-header\">\n    <div class=\"code-block-lang\">\n      <svg width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><polyline points=\"16 18 22 12 16 6\"/><polyline points=\"8 6 2 12 8 18\"/></svg>\n      <span>SystemVerilog</span>\n    </div>\n    <button class=\"code-copy-btn\" title=\"Copy code\" aria-label=\"Copy code to clipboard\">\n      <svg class=\"copy-icon\" width=\"13\" height=\"13\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"><rect x=\"9\" y=\"9\" width=\"13\" height=\"13\" rx=\"2\" ry=\"2\"/><path d=\"M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1\"/></svg>\n      <span class=\"copy-text\">Copy</span>\n    </button>\n  </div>\n  <pre class=\"code-block-content\"><code><span class=\"sv-keyword-decl\">class</span> <span class=\"sv-ident\">mytype</span> <span class=\"sv-keyword-decl\">extends</span> <span class=\"sv-uvm-type\">uvm_object</span><span class=\"sv-op\">;</span>\n\n  <span class=\"sv-qualifier\">local</span> <span class=\"sv-type\">int</span> <span class=\"sv-ident\">myint</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-qualifier\">local</span> <span class=\"sv-type\">byte</span> <span class=\"sv-ident\">mybyte</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-qualifier\">local</span> <span class=\"sv-type\">shortint</span> <span class=\"sv-ident\">myshort</span><span class=\"sv-op\">;</span> <span class=\"sv-comment\">// no access</span>\n  <span class=\"sv-qualifier\">local</span> <span class=\"sv-type\">string</span> <span class=\"sv-ident\">mystring</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-qualifier\">local</span> <span class=\"sv-ident\">obj_type</span> <span class=\"sv-ident\">myobj</span><span class=\"sv-op\">;</span>\n\n  <span class=\"sv-comment\">// provide access to integral properties</span>\n  <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-method\">set_int_local</span><span class=\"sv-op\">(</span><span class=\"sv-type\">string</span> <span class=\"sv-ident\">field_name</span><span class=\"sv-op\">,</span> <span class=\"sv-uvm-type\">uvm_bitstream_t</span> <span class=\"sv-ident\">value</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-keyword\">if</span> <span class=\"sv-op\">(</span><span class=\"sv-uvm-type\">uvm_is_match</span> <span class=\"sv-op\">(</span><span class=\"sv-ident\">field_name</span><span class=\"sv-op\">,</span> <span class=\"sv-string\">&quot;myint&quot;</span><span class=\"sv-op\">)</span><span class=\"sv-op\">)</span>\n      <span class=\"sv-ident\">myint</span> <span class=\"sv-op\">=</span> <span class=\"sv-ident\">value</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-keyword\">else</span> <span class=\"sv-keyword\">if</span> <span class=\"sv-op\">(</span><span class=\"sv-uvm-type\">uvm_is_match</span> <span class=\"sv-op\">(</span><span class=\"sv-ident\">field_name</span><span class=\"sv-op\">,</span> <span class=\"sv-string\">&quot;mybyte&quot;</span><span class=\"sv-op\">)</span><span class=\"sv-op\">)</span>\n      <span class=\"sv-ident\">mybyte</span> <span class=\"sv-op\">=</span> <span class=\"sv-ident\">value</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-keyword-decl\">endfunction</span>\n\n  <span class=\"sv-comment\">// provide access to string properties</span>\n  <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-method\">set_string_local</span><span class=\"sv-op\">(</span><span class=\"sv-type\">string</span> <span class=\"sv-ident\">field_name</span><span class=\"sv-op\">,</span> <span class=\"sv-type\">string</span> <span class=\"sv-ident\">value</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-keyword\">if</span> <span class=\"sv-op\">(</span><span class=\"sv-uvm-type\">uvm_is_match</span> <span class=\"sv-op\">(</span><span class=\"sv-ident\">field_name</span><span class=\"sv-op\">,</span> <span class=\"sv-string\">&quot;mystring&quot;</span><span class=\"sv-op\">)</span><span class=\"sv-op\">)</span>\n      <span class=\"sv-ident\">mystring</span> <span class=\"sv-op\">=</span> <span class=\"sv-ident\">value</span><span class=\"sv-op\">;</span>\n  <span class=\"sv-keyword-decl\">endfunction</span>\n\n  <span class=\"sv-comment\">// provide access to sub-objects</span>\n  <span class=\"sv-keyword-decl\">function</span> <span class=\"sv-type\">void</span> <span class=\"sv-method\">set_object_local</span><span class=\"sv-op\">(</span><span class=\"sv-type\">string</span> <span class=\"sv-ident\">field_name</span><span class=\"sv-op\">,</span> <span class=\"sv-uvm-type\">uvm_object</span> <span class=\"sv-ident\">value</span><span class=\"sv-op\">,</span>\n                                 <span class=\"sv-type\">bit</span> <span class=\"sv-method\">clone</span><span class=\"sv-op\">=</span><span class=\"sv-number\">1</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n    <span class=\"sv-keyword\">if</span> <span class=\"sv-op\">(</span><span class=\"sv-uvm-type\">uvm_is_match</span> <span class=\"sv-op\">(</span><span class=\"sv-ident\">field_name</span><span class=\"sv-op\">,</span> <span class=\"sv-string\">&quot;myobj&quot;</span><span class=\"sv-op\">)</span><span class=\"sv-op\">)</span> <span class=\"sv-keyword\">begin</span>\n      <span class=\"sv-keyword\">if</span> <span class=\"sv-op\">(</span><span class=\"sv-ident\">value</span> <span class=\"sv-op\">!=</span> <span class=\"sv-constant\">null</span><span class=\"sv-op\">)</span> <span class=\"sv-keyword\">begin</span>\n        <span class=\"sv-ident\">obj_type</span> <span class=\"sv-ident\">tmp</span><span class=\"sv-op\">;</span>\n        <span class=\"sv-comment\">// if provided value is not correct type, produce error</span>\n        <span class=\"sv-keyword\">if</span> <span class=\"sv-op\">(</span><span class=\"sv-op\">!</span><span class=\"sv-system-tf\">$cast</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">tmp</span><span class=\"sv-op\">,</span> <span class=\"sv-ident\">value</span><span class=\"sv-op\">)</span> <span class=\"sv-op\">)</span>\n          <span class=\"sv-comment\">/* error */</span>\n        <span class=\"sv-keyword\">else</span> <span class=\"sv-keyword\">begin</span>\n          <span class=\"sv-keyword\">if</span><span class=\"sv-op\">(</span><span class=\"sv-method\">clone</span><span class=\"sv-op\">)</span>\n            <span class=\"sv-system-tf\">$cast</span><span class=\"sv-op\">(</span><span class=\"sv-ident\">myobj</span><span class=\"sv-op\">,</span> <span class=\"sv-ident\">tmp</span><span class=\"sv-op\">.</span><span class=\"sv-method\">clone</span><span class=\"sv-op\">(</span><span class=\"sv-op\">)</span><span class=\"sv-op\">)</span><span class=\"sv-op\">;</span>\n          <span class=\"sv-keyword\">else</span>\n            <span class=\"sv-ident\">myobj</span> <span class=\"sv-op\">=</span> <span class=\"sv-ident\">tmp</span><span class=\"sv-op\">;</span>\n        <span class=\"sv-keyword\">end</span>\n      <span class=\"sv-keyword\">end</span>\n      <span class=\"sv-keyword\">else</span>\n        <span class=\"sv-ident\">myobj</span> <span class=\"sv-op\">=</span> <span class=\"sv-constant\">null</span><span class=\"sv-op\">;</span> <span class=\"sv-comment\">// value is null, so simply assign null to myobj</span>\n    <span class=\"sv-keyword\">end</span>\n  <span class=\"sv-keyword-decl\">endfunction</span>\n  <span class=\"sv-op\">.</span><span class=\"sv-op\">.</span><span class=\"sv-op\">.</span></code></pre>\n</div><p>Although the object designer implements these methods to provide outside access to one or more properties, they are intended for internal use (e.g., for command-line debugging and auto-configuration) and should not be called directly by the user.</p></div></div></div>"}]);}
